public int minDistance(String word1, String word2) {
    int m = word1.length(), n = word2.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (word1.charAt(i-1) == word2.charAt(j-1)) {
                dp[i][j] = dp[i-1][j-1]; // chars match, free
            } else {
                dp[i][j] = 1 + Math.min(dp[i-1][j-1],      // replace
                                Math.min(dp[i-1][j],        // delete
                                         dp[i][j-1]));      // insert
            }
        }
    }
    return dp[m][n];
}

// O(n log n) solution
public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;
    for (int num : nums) {
        // Find leftmost position where tails[pos] >= num
        int lo = 0, hi = size;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (tails[mid] < num) lo = mid + 1;
            else hi = mid;
        }
        tails[lo] = num;
        if (lo == size) size++;
    }
    return size;
}

public boolean isMatch(String s, String p) {
    int m = s.length(), n = p.length();
    boolean[][] dp = new boolean[m + 1][n + 1];
    dp[0][0] = true;
    // Handle patterns like a*, a*b*, etc. matching empty string
    for (int j = 2; j <= n; j++) {
        if (p.charAt(j-1) == '*') dp[0][j] = dp[0][j-2];
    }
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            char sc = s.charAt(i-1), pc = p.charAt(j-1);
            if (pc == '*') {
                // Zero occurrences of preceding char
                dp[i][j] = dp[i][j-2];
                // One more occurrence (if chars match)
                if (p.charAt(j-2) == '.' || p.charAt(j-2) == sc) {
                    dp[i][j] = dp[i][j] || dp[i-1][j];
                }
            } else if (pc == '.' || pc == sc) {
                dp[i][j] = dp[i-1][j-1];
            }
        }
    }
    return dp[m][n];
}

