public int maxCoins(int[] nums) {
    int n = nums.length;
    // Add sentinel boundaries
    int[] arr = new int[n + 2];
    arr[0] = arr[n + 1] = 1;
    for (int i = 0; i < n; i++) arr[i + 1] = nums[i];
    int m = n + 2;

    // dp[l][r] = max coins bursting all in open interval (l, r)
    int[][] dp = new int[m][m];
    // len is the gap between l and r (must be at least 2 for open interval)
    for (int len = 2; len < m; len++) {
        for (int l = 0; l + len < m; l++) {
            int r = l + len;
            for (int k = l + 1; k < r; k++) {
                int coins = arr[l] * arr[k] * arr[r]
                          + dp[l][k] + dp[k][r];
                dp[l][r] = Math.max(dp[l][r], coins);
            }
        }
    }
    return dp[0][m - 1];
}

public int minCut(String s) {
    int n = s.length();
    boolean[][] isPalin = new boolean[n][n];
    // Precompute palindromes
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) {
            isPalin[i][j] = (s.charAt(i) == s.charAt(j))
                         && (j - i <= 2 || isPalin[i+1][j-1]);
        }
    }
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        if (isPalin[0][i]) { dp[i] = 0; continue; }
        dp[i] = i; // max cuts = i (cut every char)
        for (int j = 1; j <= i; j++) {
            if (isPalin[j][i]) {
                dp[i] = Math.min(dp[i], dp[j-1] + 1);
            }
        }
    }
    return dp[n - 1];
}

