public int calculateMinimumHP(int[][] dungeon) {
    int m = dungeon.length, n = dungeon[0].length;
    int[][] dp = new int[m][n];
    // Base: princess cell
    dp[m-1][n-1] = Math.max(1, 1 - dungeon[m-1][n-1]);
    // Last column
    for (int i = m - 2; i >= 0; i--)
        dp[i][n-1] = Math.max(1, dp[i+1][n-1] - dungeon[i][n-1]);
    // Last row
    for (int j = n - 2; j >= 0; j--)
        dp[m-1][j] = Math.max(1, dp[m-1][j+1] - dungeon[m-1][j]);
    // Fill rest
    for (int i = m - 2; i >= 0; i--) {
        for (int j = n - 2; j >= 0; j--) {
            int best = Math.min(dp[i+1][j], dp[i][j+1]);
            dp[i][j] = Math.max(1, best - dungeon[i][j]);
        }
    }
    return dp[0][0];
}

public int cherryPickup(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    int[][][] dp = new int[m][n][n];
    // Initialize with -1 (not computed)
    for (int[][] a : dp) for (int[] b : a) Arrays.fill(b, -1);
    return dfs(grid, dp, 0, 0, n - 1, m, n);
}

private int dfs(int[][] g, int[][][] dp, int r, int c1, int c2, int m, int n) {
    if (r == m) return 0;
    if (dp[r][c1][c2] != -1) return dp[r][c1][c2];
    int cherries = g[r][c1] + (c1 != c2 ? g[r][c2] : 0);
    int best = 0;
    for (int d1 = -1; d1 <= 1; d1++) {
        for (int d2 = -1; d2 <= 1; d2++) {
            int nc1 = c1 + d1, nc2 = c2 + d2;
            if (nc1 >= 0 && nc1 < n && nc2 >= 0 && nc2 < n)
                best = Math.max(best, dfs(g, dp, r+1, nc1, nc2, m, n));
        }
    }
    dp[r][c1][c2] = cherries + best;
    return dp[r][c1][c2];
}

