public int maxProfit(int k, int[] prices) {
    int n = prices.length;
    if (n == 0) return 0;
    // If k is large enough, unlimited transactions
    if (k >= n / 2) {
        int profit = 0;
        for (int i = 1; i < n; i++)
            profit += Math.max(0, prices[i] - prices[i-1]);
        return profit;
    }
    int[][] dp = new int[k + 1][2];
    for (int t = 1; t <= k; t++) dp[t][1] = Integer.MIN_VALUE;
    for (int price : prices) {
        for (int t = k; t >= 1; t--) {
            dp[t][0] = Math.max(dp[t][0], dp[t][1] + price);
            dp[t][1] = Math.max(dp[t][1], dp[t-1][0] - price);
        }
    }
    return dp[k][0];
}

