// Returns int[] {notTake, take} for each node
int[] dfs(int node, int parent, List<List<Integer>> adj, int[] vals) {
    int notTake = 0, take = vals[node];
    for (int child : adj.get(node)) {
        if (child == parent) continue;
        int[] childDP = dfs(child, node, adj, vals);
        notTake += Math.max(childDP[0], childDP[1]); // can take child
        take += childDP[0];  // can't take child if we take node
    }
    return new int[]{notTake, take};
}

// Tree Diameter
int[] maxDiameter = {0};
int dfsHeight(int node, int par, List<List<Integer>> adj) {
    int top1 = 0, top2 = 0; // two longest paths from children
    for (int child : adj.get(node)) {
        if (child == par) continue;
        int h = 1 + dfsHeight(child, node, adj);
        if (h > top1) { top2 = top1; top1 = h; }
        else if (h > top2) top2 = h;
    }
    maxDiameter[0] = Math.max(maxDiameter[0], top1 + top2);
    return top1;
}

