public boolean canPartitionKSubsets(int[] nums, int k) {
    int total = 0;
    for (int x : nums) total += x;
    if (total % k != 0) return false;
    int target = total / k, n = nums.length;
    Arrays.sort(nums);
    if (nums[n-1] > target) return false;

    boolean[] dp = new boolean[1 << n];
    int[] curSum = new int[1 << n];
    dp[0] = true;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (!dp[mask]) continue;
        for (int i = 0; i < n; i++) {
            if ((mask >> i & 1) == 1) continue; // already used
            int next = mask | (1 << i);
            if (dp[next]) continue;
            int s = curSum[mask] + nums[i];
            if (s <= target) {
                curSum[next] = s % target; // reset on completing group
                dp[next] = true;
            }
        }
    }
    return dp[(1 << n) - 1];
}

