Map<String, Long> memo;

long solve(int pos, boolean tight, boolean started /*, extra states */) {
    if (pos == num.length()) return started ? 1 : 0; // base case
    String key = pos + "," + tight + "," + started;   // + extra states
    if (memo.containsKey(key)) return memo.get(key);

    int limit = tight ? (num.charAt(pos) - '0') : 9;
    long result = 0;
    for (int d = 0; d <= limit; d++) {
        boolean newTight   = tight && (d == limit);
        boolean newStarted = started || (d != 0);
        // Skip if this digit violates constraints
        result += solve(pos + 1, newTight, newStarted /*, updated states */);
    }
    memo.put(key, result);
    return result;
}

