public int countSpecialNumbers(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // memo[pos][mask][tight][started]
    int[][][][] memo = new int[len][1 << 10][2][2];
    for (int[][][] a : memo) for (int[][] b : a)
        for (int[] c : b) Arrays.fill(c, -1);
    return dfs(digits, memo, 0, 0, true, false);
}

private int dfs(char[] digits, int[][][][] memo,
                int pos, int mask, boolean tight, boolean started) {
    if (pos == digits.length) return started ? 1 : 0;
    int t = tight ? 1 : 0, s = started ? 1 : 0;
    if (memo[pos][mask][t][s] != -1) return memo[pos][mask][t][s];

    int limit = tight ? (digits[pos] - '0') : 9;
    int result = 0;
    for (int d = 0; d <= limit; d++) {
        if (started && ((mask >> d) & 1) == 1) continue; // already used
        boolean newTight   = tight && (d == limit);
        boolean newStarted = started || (d != 0);
        int newMask = newStarted ? (mask | (1 << d)) : mask;
        result += dfs(digits, memo, pos+1, newMask, newTight, newStarted);
    }
    return memo[pos][mask][t][s] = result;
}

public int maxResult(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n];
    dp[0] = nums[0];
    Deque<Integer> dq = new ArrayDeque<>(); // indices, decreasing dp
    dq.addLast(0);
    for (int i = 1; i < n; i++) {
        // Remove indices outside window
        while (!dq.isEmpty() && dq.peekFirst() < i - k)
            dq.pollFirst();
        dp[i] = nums[i] + dp[dq.peekFirst()];
        // Maintain decreasing deque
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i])
            dq.pollLast();
        dq.addLast(i);
    }
    return dp[n - 1];
}

