public boolean isInterleave(String s1, String s2, String s3) {
    int m = s1.length(), n = s2.length();
    if (m + n != s3.length()) return false;
    boolean[][] dp = new boolean[m + 1][n + 1];
    dp[0][0] = true;
    // Fill first row: only using s2
    for (int j = 1; j <= n; j++)
        dp[0][j] = dp[0][j-1] && s2.charAt(j-1) == s3.charAt(j-1);
    // Fill first col: only using s1
    for (int i = 1; i <= m; i++)
        dp[i][0] = dp[i-1][0] && s1.charAt(i-1) == s3.charAt(i-1);

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            char c = s3.charAt(i + j - 1);
            dp[i][j] = (dp[i-1][j] && s1.charAt(i-1) == c)
                    || (dp[i][j-1] && s2.charAt(j-1) == c);
        }
    }
    return dp[m][n];
}

public int minDifficulty(int[] jobDifficulty, int d) {
    int n = jobDifficulty.length;
    if (n < d) return -1;
    // Precompute suffix maximums for O(1) range-max queries
    int[][] maxFrom = new int[n][n];
    for (int i = 0; i < n; i++) {
        maxFrom[i][i] = jobDifficulty[i];
        for (int j = i + 1; j < n; j++)
            maxFrom[i][j] = Math.max(maxFrom[i][j-1], jobDifficulty[j]);
    }
    // dp[day][i] = min difficulty using first i+1 jobs in 'day' days
    int[][] dp = new int[d + 1][n];
    final int INF = Integer.MAX_VALUE / 2;
    for (int[] row : dp) Arrays.fill(row, INF);
    // Base: day 1, assign jobs 0..i in one block
    for (int i = 0; i < n; i++)
        dp[1][i] = maxFrom[0][i];

    for (int day = 2; day <= d; day++) {
        // Need at least 'day' jobs to assign 1 per day
        for (int i = day - 1; i < n; i++) {
            // Last block starts at j+1, ends at i
            for (int j = day - 2; j < i; j++) {
                if (dp[day-1][j] == INF) continue;
                dp[day][i] = Math.min(dp[day][i],
                                      dp[day-1][j] + maxFrom[j+1][i]);
            }
        }
    }
    return dp[d][n-1];
}

public int kInversePairs(int n, int k) {
    final int MOD = 1_000_000_007;
    // dp[j] = count of permutations of [1..i] with exactly j inverse pairs
    int[] dp = new int[k + 1];
    dp[0] = 1; // base: [1], 0 inverse pairs

    for (int i = 2; i <= n; i++) {
        // Build prefix sum of current dp
        int[] prefix = new int[k + 2];
        for (int j = 0; j <= k; j++)
            prefix[j + 1] = (prefix[j] + dp[j]) % MOD;

        int[] next = new int[k + 1];
        for (int j = 0; j <= k; j++) {
            // Sum of dp[j-p] for p in [0, min(j, i-1)]
            // = prefix[j+1] - prefix[max(0, j-i+1)]
            int lo = Math.max(0, j - (i - 1));
            next[j] = (prefix[j + 1] - prefix[lo] + MOD) % MOD;
        }
        dp = next;
    }
    return dp[k];
}

public int tallestBillboard(int[] rods) {
    // dp: difference -> max height of taller pole
    Map<Integer, Integer> dp = new HashMap<>();
    dp.put(0, 0);
    for (int rod : rods) {
        Map<Integer, Integer> next = new HashMap<>(dp);
        for (Map.Entry<Integer, Integer> e : dp.entrySet()) {
            int diff = e.getKey(), tall = e.getValue();
            // Add rod to the taller group: diff increases
            next.merge(diff + rod, tall + rod, Math::max);
            // Add rod to the shorter group
            if (diff >= rod) {
                // shorter side grows but still shorter: diff decreases
                next.merge(diff - rod, tall, Math::max);
            } else {
                // shorter side overtakes: flip who is taller
                next.merge(rod - diff, tall + rod - diff, Math::max);
            }
        }
        dp = next;
    }
    return dp.getOrDefault(0, 0);
}

public int minCostII(int[][] costs) {
    int n = costs.length, k = costs[0].length;
    // Track top-2 minimums from previous row
    int min1 = 0, min2 = 0, minIdx = -1; // min1 <= min2

    for (int i = 0; i < n; i++) {
        int newMin1 = Integer.MAX_VALUE, newMin2 = Integer.MAX_VALUE;
        int newMinIdx = -1;
        for (int j = 0; j < k; j++) {
            // If previous minimum was at same color, use min2
            int prev = (j == minIdx) ? min2 : min1;
            int cost = costs[i][j] + prev;
            if (cost < newMin1) {
                newMin2 = newMin1; newMin1 = cost; newMinIdx = j;
            } else if (cost < newMin2) {
                newMin2 = cost;
            }
        }
        min1 = newMin1; min2 = newMin2; minIdx = newMinIdx;
    }
    return min1;
}

public int checkRecord(int n) {
    final int MOD = 1_000_000_007;
    // dp[abs][trailing_L] = count of valid strings with these properties
    // abs in {0,1}, trailing_L in {0,1,2}
    long[][] dp = new long[2][3];
    dp[0][0] = 1; // empty string

    for (int i = 0; i < n; i++) {
        long[][] next = new long[2][3];
        for (int abs = 0; abs <= 1; abs++) {
            for (int tl = 0; tl <= 2; tl++) {
                if (dp[abs][tl] == 0) continue;
                long ways = dp[abs][tl];
                // Place 'P': resets trailing L
                next[abs][0] = (next[abs][0] + ways) % MOD;
                // Place 'L': increment trailing L (only if < 2)
                if (tl < 2)
                    next[abs][tl + 1] = (next[abs][tl + 1] + ways) % MOD;
                // Place 'A': only if no A yet, resets trailing L
                if (abs == 0)
                    next[1][0] = (next[1][0] + ways) % MOD;
            }
        }
        dp = next;
    }
    long ans = 0;
    for (long[] row : dp) for (long v : row) ans = (ans + v) % MOD;
    return (int) ans;
}

public boolean canCross(int[] stones) {
    // Map each stone position to set of jump sizes that can reach it
    Map<Integer, Set<Integer>> map = new HashMap<>();
    for (int s : stones) map.put(s, new HashSet<>());
    map.get(0).add(0); // start with jump size 0 at stone 0

    for (int i = 0; i < stones.length - 1; i++) {
        int pos = stones[i];
        for (int k : map.get(pos)) {
            // Try jumps of size k-1, k, k+1
            for (int dk = -1; dk <= 1; dk++) {
                int next = pos + k + dk;
                if (k + dk <= 0) continue; // must jump at least 1
                if (map.containsKey(next)) {
                    map.get(next).add(k + dk);
                }
            }
        }
    }
    return !map.get(stones[stones.length - 1]).isEmpty();
}

public int numMusicPlaylists(int n, int goal, int k) {
    final long MOD = 1_000_000_007L;
    // dp[i][j] = playlists of length i with exactly j distinct songs
    long[][] dp = new long[goal + 1][n + 1];
    dp[0][0] = 1;

    for (int i = 1; i <= goal; i++) {
        for (int j = 1; j <= Math.min(i, n); j++) {
            // Add a new song: (n - (j-1)) choices
            dp[i][j] = (dp[i-1][j-1] * (n - j + 1)) % MOD;
            // Replay an old song: max(0, j-k) choices
            if (j > k) {
                dp[i][j] = (dp[i][j] + dp[i-1][j] * (j - k)) % MOD;
            }
        }
    }
    return (int) dp[goal][n];
}
